def sliding_windows(values: list[int], size: int) -> list[list[int]]:
    if size <= 0:
        raise ValueError("size must be positive")
    if size > len(values):
        return []
    windows = []
    for start in range(len(values) - size + 1):
        windows.append(values[start:start + size])
    return windows
